using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;using Staybnb.Models;using Staybnb.Services;using Staybnb.ViewModels;
namespace Staybnb.Controllers;
[Authorize] public class MessagesController(ApplicationDbContext db,UserManager<ApplicationUser> users,ActivityLogger logger,NotificationService notifications):Controller {
 public async Task<IActionResult> Index(){var uid=users.GetUserId(User)!;return View(await db.Messages.Include(m=>m.Sender).Include(m=>m.Receiver).Where(m=>m.SenderId==uid||m.ReceiverId==uid).OrderByDescending(m=>m.SentAt).ToListAsync());}
 [HttpGet] public async Task<IActionResult> Compose(string? receiverId){var vm=new MessageViewModel{ReceiverId=receiverId??""};ViewBag.Users=await users.Users.Where(u=>u.Id!=users.GetUserId(User)).OrderBy(u=>u.Email).Select(u=>new Microsoft.AspNetCore.Mvc.Rendering.SelectListItem{Text=u.FullName??u.Email,Value=u.Id}).ToListAsync();return View(vm);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Compose(MessageViewModel vm){if(!ModelState.IsValid)return await ComposeInvalid(vm);var sender=users.GetUserId(User)!;if(await users.FindByIdAsync(vm.ReceiverId)==null){ModelState.AddModelError(nameof(vm.ReceiverId),"Choose a valid recipient.");return await ComposeInvalid(vm);}var m=new Message{SenderId=sender,ReceiverId=vm.ReceiverId,Content=vm.Content};db.Messages.Add(m);await db.SaveChangesAsync();await notifications.AddAsync(vm.ReceiverId,"New message received","Message","/Messages/Index");await logger.LogAsync(sender,"Sent a message","Message",$"MessageId={m.Id}");return RedirectToAction(nameof(Index));}
 private async Task<IActionResult> ComposeInvalid(MessageViewModel vm){ViewBag.Users=await users.Users.Where(u=>u.Id!=users.GetUserId(User)).Select(u=>new Microsoft.AspNetCore.Mvc.Rendering.SelectListItem{Text=u.FullName??u.Email,Value=u.Id}).ToListAsync();return View(vm);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> MarkRead(int id){var uid=users.GetUserId(User)!;var m=await db.Messages.FirstOrDefaultAsync(m=>m.Id==id&&m.ReceiverId==uid);if(m==null)return NotFound();m.IsRead=true;await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpGet] public async Task<IActionResult> Reply(int id){var uid=users.GetUserId(User)!;var m=await db.Messages.FirstOrDefaultAsync(m=>m.Id==id&&(m.ReceiverId==uid||m.SenderId==uid));if(m==null)return NotFound();var receiver=m.SenderId==uid?m.ReceiverId:m.SenderId;return RedirectToAction(nameof(Compose),new{receiverId=receiver});}
}
